<script setup>
import {computed,onMounted,ref} from 'vue'
import {modules} from '@/api/mes/master'
const rows=ref([]),busy=ref(false),updated=ref('')
const metrics=computed(()=>rows.value.filter(r=>r.count!==undefined))
const groups=computed(()=>[...new Set(rows.value.map(r=>r.groupName))])
async function load(){busy.value=true;try{rows.value=(await modules()).data;updated.value=new Date().toLocaleString('zh-CN')}finally{busy.value=false}}
onMounted(load)
</script>
<template><div v-loading="busy" class="mes-dashboard"><header><div><div class="eyebrow">JUXING / MANUFACTURING EXECUTION</div><h1>MES 生产工作台</h1><p>聚星数据平台-制造MES</p></div><el-button icon="Refresh" @click="load">刷新</el-button></header><section class="metrics"><el-card v-for="item in metrics" :key="item.key" shadow="never" @click="$router.push(item.route)"><span>{{item.title}}</span><strong>{{item.count}}</strong><small>当前授权范围内的资料</small></el-card></section><el-alert type="info" :closable="false" show-icon title="若依业务迁移正在进行。下方明确标注各模块状态；工位和 TV 当前仍连接原 MES 服务。"/><section v-for="group in groups" :key="group" class="module-group"><h2>{{group}}</h2><div class="modules"><button v-for="item in rows.filter(r=>r.groupName===group)" :key="item.key" class="module" @click="$router.push(item.route)"><div><b>{{item.title}}</b><el-tag :type="item.status==='available'?'success':'warning'" size="small">{{item.status==='available'?'已接入':'迁移中'}}</el-tag></div><p>{{item.description}}</p><span>{{item.status==='available'?'打开模块 →':'查看迁移状态 →'}}</span></button></div></section><footer>数据来自当前若依服务 · 更新于 {{updated||'加载中'}}</footer></div></template>
<style scoped>.mes-dashboard{padding:30px;background:#f3f6fa;min-height:100vh}.mes-dashboard header{display:flex;align-items:center;justify-content:space-between;margin-bottom:26px}.eyebrow{color:#238c9e;font-size:11px;letter-spacing:2px;font-weight:700}h1{font-size:28px;margin:12px 0;color:var(--el-text-color-primary)}header p,footer{color:var(--el-text-color-secondary);font-size:13px}.metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:18px;margin-bottom:24px}.metrics .el-card{border-radius:12px;cursor:pointer}.metrics span{font-size:13px;color:var(--el-text-color-secondary)}.metrics strong{display:block;font-size:32px;color:#173b55;margin:18px 0}.metrics small{font-size:11px;color:var(--el-text-color-secondary)}.module-group{margin-top:30px}.module-group h2{font-size:17px}.modules{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.module{text-align:left;background:var(--el-bg-color);border:1px solid var(--el-border-color-light);border-radius:10px;padding:22px;cursor:pointer;color:var(--el-text-color-primary)}.module:hover{border-color:#3099a9;box-shadow:0 4px 14px #173b550c}.module>div{display:flex;gap:12px;justify-content:space-between;align-items:center}.module p{font-size:13px;color:var(--el-text-color-secondary);line-height:1.8;min-height:46px}.module>span{font-size:12px;color:#268e9e}footer{margin-top:28px}@media(max-width:1000px){.metrics{grid-template-columns:repeat(3,1fr)}.modules{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.mes-dashboard{padding:16px}.metrics,.modules{grid-template-columns:1fr}}</style>
